from .fine_range_common import OUT,condition,sha,atomic_json
def main():
    p=json.loads((OUT/'protocol.json').read_text());m=json.loads((OUT/'manifest.json').read_text());assert json.loads((OUT/'evidence_audit.json').read_text())['passed'];native=json.loads((OUT/'native_audit.json').read_text());rows=[];total=0
    for name in ['coarse','fine']:
        c=condition(p,name);controls=p['control_artifacts'][str(c['group'])];n=sum(r['weights'] for r in controls);assert n==p['converted_weights'];per_forward=4*n*c['samples'];updates=0
        for seed in p['sampling_seeds']:
            r=json.loads((OUT/'runs'/f'{name}_seed{seed}/run.json').read_text());assert r['free_node_updates']==per_forward;updates+=r['free_node_updates']
        payload=sum(r['parameter_payload_bytes'] for r in controls);flags=sum(r['group_flag_bytes'] for r in controls);other=p['model_unique_parameters']-n;row={'condition':name,'group':c['group'],'logical_pbits_per_converted_weight':1,'converted_logical_pbits':n,'remaining_deterministic_parameters':other,'samples_per_projection_per_bank':c['samples'],'banks_per_32context_forward':4,'samples_per_weight_over_32context_forward':4*c['samples'],'sum_projection_samples_per_bank':24*c['samples'],'max_projection_samples':c['samples'],'node_updates_per_32context_forward':per_forward,'node_updates_all5seeds':updates,'mean_node_updates_per_scored_target_in_this_teacher_forced_batch':per_forward/2048,'parameter_control_range_bias_payload_bytes':payload,'configuration_bytes':flags,'bits_per_converted_weight_excluding_binary_state':8*payload/n,'deterministic_remaining_FP32_parameter_bytes':4*other,'logical_serialized_mixed_parameter_bytes_excluding_state_hardware_runtime':payload+flags+4*other,'rough_worstcase_normalized_bipolar_sigma':1/math.sqrt(c['samples']),'rough_normalized_bipolar_effective_bits':.5*math.log2(c['samples'])};rows.append(row);total+=updates
    assert total==m['native_observed_updates'] and rows[0]['node_updates_all5seeds']==2*rows[1]['node_updates_all5seeds'];ledger={'production_node_updates':total,'independent_native_replay_updates':native['native_updates_replayed'],'all_executed_native_updates_this_confirmation':total+native['native_updates_replayed'],'source_sha256':sha(__file__),'rows':rows,'scope':'Teacher-forced32 contexts/65 input positions/2048 targets with one draw bank per8 contexts. Per-target divisions are evaluation-batch counters, not autoregressive generation costs. Binary pbit state, controller/range payload, deterministic parameters and software/hardware runtime memory are separate. Rough bits use normalized bipolar scalar IID variance only, ignoring finite-control bias; not absolute local-weight precision, standard ENOB or memory bits. No measured energy/physical latency/area inferred.'};atomic_json(OUT/'resource_ledger.json',ledger);print(json.dumps(ledger,indent=2))
